import type {
  QuoteDetail,
  QuoteListItem,
  QuoteLineItem,
  CreateQuoteFormData,
  CreateLineItemData,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface QuotesListResponse {
  quotes: QuoteListItem[]
  total: number
}

interface UpdateQuoteInput {
  customerId?: string | null
  notes?: string
}

interface UpdateLineItemInput {
  lineType: 'part' | 'labor' | 'bicycle'
  description?: string
  quantity?: number
  unitPriceNet?: number
  vatRateId?: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}

// ---------------------------------------------------------------------------
// API Functions — Quote CRUD
// ---------------------------------------------------------------------------

/** Get paginated quote list with optional status filter. */
export async function getQuotes(statusFilter?: string): Promise<QuotesListResponse> {
  const params = new URLSearchParams()
  if (statusFilter) params.set('status', statusFilter)

  const response = await fetch(`/api/quotes?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch quotes list')
  }

  return response.json()
}

/** Get a single quote by ID with line items. */
export async function getQuote(id: string): Promise<QuoteDetail> {
  const response = await fetch(`/api/quotes/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch quote')
  }

  return response.json()
}

/** Create a new draft quote. */
export async function createQuote(input: CreateQuoteFormData): Promise<QuoteDetail> {
  const response = await fetch('/api/quotes', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      customerId: input.customerId,
      notes: input.notes || null,
    }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create quote' }))
    throw new Error(error.error || 'Failed to create quote')
  }

  return response.json()
}

/** Update a draft quote's fields. */
export async function updateQuote(id: string, input: UpdateQuoteInput): Promise<QuoteDetail> {
  const response = await fetch(`/api/quotes/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      ...(input.customerId !== undefined && { customerId: input.customerId }),
      ...(input.notes !== undefined && { notes: input.notes || null }),
    }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update quote' }))
    throw new Error(error.error || 'Failed to update quote')
  }

  return response.json()
}

/** Delete a draft quote. */
export async function deleteQuote(id: string): Promise<void> {
  const response = await fetch(`/api/quotes/${id}`, {
    method: 'DELETE',
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to delete quote' }))
    throw new Error(error.error || 'Failed to delete quote')
  }
}

