/** Add a line item to a quote. */
export async function createQuoteLineItem(quoteId: string, input: CreateLineItemData): Promise<QuoteLineItem> {
  const response = await fetch(`/api/quotes/${quoteId}/lines`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create line item' }))
    throw new Error(error.error || 'Failed to create line item')
  }

  return response.json()
}

/** Update an existing line item. */
export async function updateQuoteLineItem(quoteId: string, lineItemId: string, input: UpdateLineItemInput): Promise<QuoteLineItem> {
  const response = await fetch(`/api/quotes/${quoteId}/lines/${lineItemId}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update line item' }))
    throw new Error(error.error || 'Failed to update line item')
  }

  return response.json()
}

/** Delete a line item from a quote. */
export async function deleteQuoteLineItem(quoteId: string, lineItemId: string): Promise<void> {
  const response = await fetch(`/api/quotes/${quoteId}/lines/${lineItemId}`, {
    method: 'DELETE',
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to delete line item' }))
    throw new Error(error.error || 'Failed to delete line item')
  }
}
