        const response = await fetch(`/api/customers?${params.toString()}`)
        if (!response.ok) throw new Error('Failed to fetch customers')

        const data = await response.json() as { items: QuoteCustomer[]; total: number }
        setCustomers(data.items ?? [])
      } catch (err) {
        console.error('[CreateQuoteForm] Failed to load customers:', err)
        setCustomers([])
      } finally {
        setLoading(false)
      }
    }

    fetchCustomers()
