export function QuoteDetailPanel({ quoteId }: QuoteDetailPanelProps) {
  const navigate = useNavigate()
  const [quote, setQuote] = useState<QuoteDetail | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showAddLineItem, setShowAddLineItem] = useState(false)

  // Fetch quote detail
  useEffect(() => {
    async function fetchQuote() {
      try {
        const data = await getQuote(quoteId)
        setQuote(data)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load quote')
      } finally {
        setLoading(false)
      }
    }

    fetchQuote()
  }, [quoteId])

  // Handle line item refresh after add/update/delete
  const handleLineItemChange = async () => {
    try {
      const updated = await getQuote(quoteId)
      setQuote(updated)
    } catch (err) {
      console.error('[QuoteDetailPanel] Failed to refresh quote:', err)
    }
  }

  // Handle adding a new line item
  const handleAddLineItem = async (data: CreateLineItemData) => {
    try {
      await createQuoteLineItem(quoteId, data)
      setShowAddLineItem(false)
      await handleLineItemChange()
    } catch (err) {
      console.error('[QuoteDetailPanel] Failed to add line item:', err)
    }
  }

  // Handle deleting the quote
  const handleDeleteQuote = async () => {
    if (!quote || quote.status !== 'draft') return
    if (window.confirm('Are you sure you want to delete this quote? This cannot be undone.')) {
      try {
        await deleteQuote(quoteId)
        navigate('/quotes')
      } catch (err) {
        console.error('[QuoteDetailPanel] Failed to delete quote:', err)
      }
    }
  }

  // Calculate totals
  const totalNet = quote?.lineItems.reduce((sum, item) => sum + item.lineTotalNet, 0) ?? 0
  const totalVat = quote?.lineItems.reduce((sum, item) => sum + item.lineTotalVat, 0) ?? 0
  const totalGross = quote?.lineItems.reduce((sum, item) => sum + item.lineTotalGross, 0) ?? 0

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="h-6 w-6 animate-spin rounded-full border-2 border-blue-600 border-t-transparent" />
      </div>
    )
  }

  if (error || !quote) {
    return (
      <div className="space-y-4">
        <button
          onClick={() => navigate('/quotes')}
          className="inline-flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Quotes
        </button>
        <div className="rounded-lg bg-red-50 p-4 text-sm text-red-700">
          {error || 'Quote not found'}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <button
          onClick={() => navigate('/quotes')}
          className="inline-flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to Quotes
        </button>

        {quote.status === 'draft' && (
          <button
            onClick={handleDeleteQuote}
            className="inline-flex items-center gap-1 rounded-md px-3 py-1.5 text-sm font-medium text-red-600 hover:bg-red-50"
          >
            <Trash2 className="h-4 w-4" />
            Delete Quote
          </button>
        )}
      </div>

      {/* Quote Header Card */}
      <div className="rounded-lg border border-gray-200 bg-white p-6 shadow-sm">
        <div className="flex items-start justify-between">
          <div>
            <h1 className="text-xl font-bold text-gray-900">{quote.quoteNumber}</h1>
            <p className="mt-1 text-sm text-gray-500">
              Created {new Date(quote.createdAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' })}
            </p>
          </div>
          <StatusBadge status={quote.status} />
        </div>

        {/* Notes */}
        {quote.notes && (
          <div className="mt-4 rounded-lg bg-gray-50 p-3">
            <p className="text-sm text-gray-700 whitespace-pre-wrap">{quote.notes}</p>
          </div>
        )}

        {/* Customer */}
        {quote.customerId && (
          <div className="mt-4 flex items-center gap-2 text-sm text-gray-600">
            <span className="font-medium">Customer:</span>
            <span>{`Customer ${quote.customerId.slice(0, 8)}...`}</span>
          </div>
        )}
      </div>

      {/* Line Items Section */}
      <div className="rounded-lg border border-gray-200 bg-white shadow-sm">
        {/* Section Header */}
        <div className="flex items-center justify-between border-b border-gray-200 px-6 py-4">
          <h2 className="text-base font-semibold text-gray-900">Line Items</h2>
          {quote.status === 'draft' && (
            <button
              onClick={() => setShowAddLineItem(true)}
              className="inline-flex items-center gap-1 rounded-lg bg-blue-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-blue-700"
            >
              <Plus className="h-3 w-3" />
