describe('GET /api/quotes/:id', () => {
  it('should return 404 for non-existent quote', async () => {
    const res = await app.request('/api/quotes/nonexistent-id')

    expect(res.status).toBe(404)
  })

  it('should return full quote detail with line items', async () => {
    // Seed data
    await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

    const resCreate = await app.request('/api/quotes', {
      method: 'POST',
      body: JSON.stringify({ notes: 'Quote with items' }),
      headers: { 'Content-Type': 'application/json' },
    })
    const created = (await resCreate.json()) as QuoteResponse

    // Add a line item directly to test retrieval
    await db.insert(quoteLineItems).values({
      id: 'li1',
      quoteId: created.id,
      lineType: 'part',
      partId: null,
      laborServiceId: null,
      description: 'Bearing 6205',
      quantity: 2,
      unitPriceNet: 1000,
      vatRateId: 'vat-standard',
      discountPercent: null,
      lineTotalNet: 2000,
      lineTotalVat: 420,
      lineTotalGross: 2420,
    })

    const res = await app.request(`/api/quotes/${created.id}`)

    expect(res.status).toBe(200)

