describe('PATCH /api/quotes/:id', () => {
  it('should update notes on a draft quote', async () => {
    const resCreate = await app.request('/api/quotes', {
      method: 'POST',
      body: JSON.stringify({ notes: 'Original note' }),
      headers: { 'Content-Type': 'application/json' },
    })
    const created = (await resCreate.json()) as QuoteResponse

